from __future__ import absolute_import
import time
from selenium.webdriver.common.by import By
from taf.selenium.gnb.oam.coam.classical import pages


class Software(pages.Software):
    """
    The class corresponding to software page on selenium_coam web, all operations under software
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Software, self).__init__(driver, download_checker)
        self._beam_set_realization_software = BeamSetRealizationSoftwarePage(driver, download_checker)


class BeamSetRealizationSoftwarePage(pages.software.BeamSetRealizationSoftwarePage):
    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePage, self).__init__(driver, download_checker)
        self._view_panel = BeamSetRealizationSoftwarePageViewPanel(driver, download_checker)

    def generate_bst_package(self, sw_file, ru_variant, bsr_id, custom_beam_name, tapering_profile=None, timeout=60):
        return self._view_panel.generate_bst_package(sw_file,
                                                     ru_variant,
                                                     bsr_id,
                                                     custom_beam_name,
                                                     tapering_profile,
                                                     timeout)


class BeamSetRealizationSoftwarePageViewPanel(pages.software.BeamSetRealizationSoftwarePageViewPanel):
    _LOAD_SW_FILE_HIDDEN_BUTTON_CSS = "div[class='diagnostic-validation-input-group'] ui-file-input input"
    _LOAD_SW_FILE_HIDDEN_BUTTON_XPATH = '//div[div[contains(@title, "SW file")]]//input[@type="file"]'
    _RU_VARIANT_INPUT_XPATH = '//div[div[contains(@title, "RU variant")]]//input'
    _TAPERING_PROFILE_BUTTON_XPATH = '//div[div[contains(@title, "Tapering profile")]]//div[@role="button"]/span'
    _TAPERING_PROFILE_OPTION_XPATH = '//div[div[contains(@title, "Tapering profile")]]//li'
    _BSR_ID_INPUT_XPATH = '//div[div[contains(@title, "BSR ID")]]//input'
    _CUSTOM_BEAM_SET_NAME_XPATH = '//div[div[contains(@title, "Custom beam set name")]]//input'
    _GENERATE_BSR_PACKAGE_BUTTON_XPATH = '//button[*[contains(text(), "Generate BSR package")]]'

    def __init__(self, driver, download_checker):
        super(BeamSetRealizationSoftwarePageViewPanel, self).__init__(driver, download_checker)

    def generate_bst_package(self, sw_file, ru_variant, bsr_id, custom_beam_name, tapering_profile, timeout):
        self.load_file_from_hidden_button(self._LOAD_SW_FILE_HIDDEN_BUTTON_CSS,
                                          self._LOAD_SW_FILE_HIDDEN_BUTTON_XPATH,
                                          sw_file,
                                          timeout)
        self.insert_text_to_enable_element((By.XPATH, self._RU_VARIANT_INPUT_XPATH), ru_variant)
        if tapering_profile:
            self.select_element_from_dropdown_list_by_text_and_click(
                tapering_profile,
                (By.XPATH, self._TAPERING_PROFILE_BUTTON_XPATH),
                (By.XPATH, self._TAPERING_PROFILE_OPTION_XPATH),
                timeout
            )
        self.insert_text_to_enable_element((By.XPATH, self._BSR_ID_INPUT_XPATH), bsr_id)
        self.insert_text_to_enable_element((By.XPATH, self._CUSTOM_BEAM_SET_NAME_XPATH), custom_beam_name)
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._GENERATE_BSR_PACKAGE_BUTTON_XPATH), timeout)
        return self.download_files(start_time)
